<!doctype html>
<html lang="zh-CN">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>完成第三方登录</title><link rel="stylesheet" href="/assets/css/style.css"><style>.oauth-box{max-width:520px;margin:28px auto;padding:18px}.oauth-profile{display:flex;gap:12px;align-items:center;margin:12px 0;padding:12px;border:1px solid var(--line-soft,#e2e8f0);border-radius:16px;background:var(--input-bg,#f8fafc)}.oauth-avatar{width:44px;height:44px;border-radius:50%;object-fit:cover;background:#e2e8f0}.oauth-tabs{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:14px 0}.oauth-tabs button{height:34px;border-radius:999px;border:1px solid var(--line-soft,#e2e8f0);background:#fff;font-weight:900;color:#64748b}.oauth-tabs button.active{background:var(--primary,#0284c7);color:#fff;border-color:var(--primary,#0284c7)}.oauth-panel{display:none}.oauth-panel.active{display:grid;gap:10px}.login-error{margin:12px 0;padding:12px;border-radius:12px;background:#fff0f0;border:1px solid #fca5a5;color:#b91c1c}</style></head>
<body><?php require __DIR__ . '/../layouts/topbar.php'; ?><main class="oauth-box card"><h2 style="margin:0 0 8px;">完成登录</h2><div style="font-size:13px;color:#64748b;line-height:1.7;">这是第一次使用 <?= htmlspecialchars($providers[$provider]['name'] ?? $provider) ?> 登录。可以创建新账号，也可以绑定已有账号。</div><?php if(!empty($error)): ?><div class="login-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><div class="oauth-profile"><?php if(!empty($profile['avatar'])): ?><img class="oauth-avatar" src="<?= htmlspecialchars($profile['avatar']) ?>" alt=""><?php else: ?><div class="oauth-avatar"></div><?php endif; ?><div><strong><?= htmlspecialchars((string)($profile['nickname'] ?? '第三方用户')) ?></strong><div style="font-size:12px;color:#94a3b8;">来自 <?= htmlspecialchars($providers[$provider]['name'] ?? $provider) ?></div></div></div><div class="oauth-tabs"><button type="button" class="active" data-oauth-tab="register">新建账号</button><button type="button" data-oauth-tab="bind">绑定已有账号</button></div><form class="oauth-panel active" data-oauth-panel="register" method="post"><?= csrf_field() ?><input type="hidden" name="mode" value="register"><label style="display:grid;gap:6px;"><span style="font-size:12px;color:#64748b;font-weight:900;">昵称</span><input class="input" name="nickname" value="<?= htmlspecialchars((string)($profile['nickname'] ?? '')) ?>" required></label><button class="btn" type="submit">创建并登录</button></form><form class="oauth-panel" data-oauth-panel="bind" method="post"><?= csrf_field() ?><input type="hidden" name="mode" value="bind"><input class="input" name="account" placeholder="邮箱 / 用户名 / 账号ID" required><input class="input" name="password" type="password" placeholder="账号密码" required><button class="btn" type="submit">绑定并登录</button></form></main><script>(function(){const tabs=document.querySelectorAll('[data-oauth-tab]');const panels=document.querySelectorAll('[data-oauth-panel]');tabs.forEach(t=>t.onclick=()=>{tabs.forEach(x=>x.classList.toggle('active',x===t));panels.forEach(p=>p.classList.toggle('active',p.dataset.oauthPanel===t.dataset.oauthTab));});})();</script></body></html>
